import json, ast, re, sys
from collections import Counter, defaultdict

corpus = json.load(open('/home/user/lypning/.hillclimb/corpus.json'))
routes = json.load(open('/tmp/mu-work/routes.json'))

progs = []
nparse = 0
for e in corpus:
    src = e['program']
    try:
        tree = ast.parse(src)
    except SyntaxError:
        tree = None
    else:
        nparse += 1
    progs.append((e['id'], src, tree, routes.get(e['id'],{}).get('engine','?')))
print("corpus loaded:", len(progs), " ast-parsed:", nparse, file=sys.stderr)

def walk(tree):
    return ast.walk(tree) if tree is not None else []

def attrname(node):
    return node.attr if isinstance(node, ast.Attribute) else None

def kwnames(call):
    return {k.arg for k in call.keywords if k.arg}

# ---- detectors -------------------------------------------------------------
def d_sort_key(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name) and f.id == 'sorted' and 'key' in kwnames(n):
                return True
            if isinstance(f, ast.Attribute) and f.attr == 'sort' and 'key' in kwnames(n):
                return True
    return False

def d_sort_any(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name) and f.id == 'sorted': return True
            if isinstance(f, ast.Attribute) and f.attr == 'sort': return True
    return False

def d_minmax_key(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in ('min','max') and 'key' in kwnames(n):
            return True
    return False

def d_round_ndigits(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='round' and len(n.args)>=2:
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='round' and 'ndigits' in kwnames(n):
            return True
    return False

def d_round_any(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='round':
            return True
    return False

NAN_RE = re.compile(r"""float\(\s*['"][+-]?nan['"]\s*\)|math\.nan|\bnan\b""", re.I)
def d_nan_source(src, t):
    return bool(NAN_RE.search(src))
def d_nan_strict(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='float' \
           and n.args and isinstance(n.args[0], ast.Constant) and isinstance(n.args[0].value,str) \
           and n.args[0].value.strip().lower().lstrip('+-')=='nan':
            return True
        if isinstance(n, ast.Attribute) and n.attr=='nan':
            return True
    return False

def d_int_call(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='int' and n.args:
            return True
    return False
def d_int_nonliteral(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='int' and n.args:
            a=n.args[0]
            if not (isinstance(a, ast.Constant) and isinstance(a.value,(int,float))):
                return True
    return False
def d_int_underscore_literal(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='int' and n.args:
            a=n.args[0]
            if isinstance(a, ast.Constant) and isinstance(a.value,str) and '_' in a.value:
                return True
    return False

SPEC_RE = re.compile(r'\{[^{}]*:[^{}]*\}')
def specs_of(src, t):
    out=[]
    if t is not None:
        for n in walk(t):
            if isinstance(n, ast.FormattedValue) and n.format_spec is not None:
                # join constant parts
                s=''.join(p.value for p in n.format_spec.values if isinstance(p, ast.Constant) and isinstance(p.value,str))
                out.append(s)
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr=='format' \
               and isinstance(n.func.value, ast.Constant) and isinstance(n.func.value.value,str):
                for m in SPEC_RE.finditer(n.func.value.value):
                    out.append(m.group(0).split(':',1)[1][:-1])
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='format' and len(n.args)>=2 \
               and isinstance(n.args[1], ast.Constant) and isinstance(n.args[1].value,str):
                out.append(n.args[1].value)
    return out

def d_group_any(src, t):
    for s in specs_of(src,t):
        body = s
        if re.search(r'[,_]', body): return True
    return False
def d_group_float(src, t):
    for s in specs_of(src,t):
        if re.search(r'[,_]', s) and re.search(r'[eEfFgG%]\s*$', s): return True
    return False

SEARCH_METHODS = ('find','rfind','index','rindex','count','startswith','endswith')
def d_strsearch_start(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr in SEARCH_METHODS and len(n.args)>=2:
            return True
    return False
def d_strsearch_any(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr in SEARCH_METHODS:
            return True
    return False

def d_json_parse(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr in ('loads','load') \
           and isinstance(n.func.value, ast.Name) and n.func.value.id=='json':
            return True
    return False
HOOKS={'object_hook','object_pairs_hook','parse_float','parse_int','parse_constant'}
def d_json_hooks(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and kwnames(n) & HOOKS:
            return True
    return False

def d_isinstance_int(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='isinstance' and len(n.args)>=2:
            a=n.args[1]
            names=[]
            if isinstance(a, ast.Name): names=[a.id]
            elif isinstance(a, ast.Tuple): names=[x.id for x in a.elts if isinstance(x, ast.Name)]
            if 'int' in names or 'bool' in names: return True
    return False
def d_bool_int_mix(src, t):
    # isinstance(...,int) OR True/False used as dict key/set member alongside ints
    return d_isinstance_int(src,t)

MUT_METHODS={'pop','popitem','clear','update','setdefault'}
def d_dict_mut_iter(src, t):
    # for-loop over X or X.keys()/items()/values(); body mutates X
    for n in walk(t):
        if not isinstance(n, (ast.For, ast.comprehension)): continue
        it = n.iter
        base=None
        if isinstance(it, ast.Call) and isinstance(it.func, ast.Attribute) and it.func.attr in ('keys','items','values'):
            base=it.func.value
        elif isinstance(it, ast.Name) or isinstance(it, ast.Attribute):
            base=it
        if base is None: continue
        bname = base.id if isinstance(base, ast.Name) else None
        if bname is None: continue
        body = n.body if isinstance(n, ast.For) else []
        for b in ast.walk(ast.Module(body=body, type_ignores=[]) if body else ast.Module(body=[],type_ignores=[])):
            if isinstance(b, ast.Delete):
                for tgt in b.targets:
                    if isinstance(tgt, ast.Subscript) and isinstance(tgt.value, ast.Name) and tgt.value.id==bname:
                        return True
            if isinstance(b, ast.Assign):
                for tgt in b.targets:
                    if isinstance(tgt, ast.Subscript) and isinstance(tgt.value, ast.Name) and tgt.value.id==bname:
                        return True
            if isinstance(b, ast.Call) and isinstance(b.func, ast.Attribute) and b.func.attr in MUT_METHODS \
               and isinstance(b.func.value, ast.Name) and b.func.value.id==bname:
                return True
    return False

VIEWS=('keys','items','values')
def _isview(x):
    return isinstance(x, ast.Call) and isinstance(x.func, ast.Attribute) and x.func.attr in VIEWS and not x.args
def d_dict_view_cmp(src, t):
    for n in walk(t):
        if isinstance(n, ast.Compare):
            ops=[type(o).__name__ for o in n.ops]
            sides=[n.left]+list(n.comparators)
            if any(_isview(s) for s in sides) and any(o in ('Eq','NotEq','LtE','GtE','Lt','Gt','In','NotIn') for o in ops):
                return True
        if isinstance(n, ast.BinOp) and type(n.op).__name__ in ('BitAnd','BitOr','Sub','BitXor'):
            if _isview(n.left) or _isview(n.right): return True
    return False

def d_int_truediv(src, t):
    for n in walk(t):
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div):
            return True
    return False
def d_int_truediv_big(src, t):
    BIG=2**53
    for n in walk(t):
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div):
            for side in (n.left, n.right):
                if isinstance(side, ast.Constant) and isinstance(side.value,int) and abs(side.value)>BIG:
                    return True
                if isinstance(side, ast.BinOp) and isinstance(side.op, ast.Pow):
                    return True
    return False

PCT_SPEC = re.compile(r'%([-+ #0]*)(\*|\d+)?(?:\.(\*|\d+))?([hlL]?)([diouxXeEfFgGcrsa%])')
def _risky_pct(s):
    for m in PCT_SPEC.finditer(s):
        flags, width, prec, _, conv = m.groups()
        if conv=='%': continue
        if '0' in flags and ('-' in flags or prec is not None):
            return True
    return False
def d_printf_zero(src, t):
    for n in walk(t):
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Mod) and isinstance(n.left, ast.Constant) \
           and isinstance(n.left.value, str) and _risky_pct(n.left.value):
            return True
        if isinstance(n, ast.Constant) and isinstance(n.value,str) and _risky_pct(n.value):
            return True
    return False
def d_printf_any(src, t):
    for n in walk(t):
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Mod) and isinstance(n.left, ast.Constant) \
           and isinstance(n.left.value,str) and '%' in n.left.value:
            return True
    return False

DET = [
 ('sort:key=',            d_sort_key),
 ('sort:any',             d_sort_any),
 ('min/max key=',         d_minmax_key),
 ('round(x,n)',           d_round_ndigits),
 ('round(any)',           d_round_any),
 ('nan:strict',           d_nan_strict),
 ('nan:textual',          d_nan_source),
 ('int(x) any',           d_int_call),
 ('int(non-literal)',     d_int_nonliteral),
 ('int("..._...")',       d_int_underscore_literal),
 ('spec , or _',          d_group_any),
 ('spec , or _ +floattype', d_group_float),
 ('str search w/ start',  d_strsearch_start),
 ('str search any',       d_strsearch_any),
 ('json.loads/load',      d_json_parse),
 ('json hook kwargs',     d_json_hooks),
 ('isinstance(...,int)',  d_isinstance_int),
 ('dict mutate in loop',  d_dict_mut_iter),
 ('dict view compare',    d_dict_view_cmp),
 ('any / division',       d_int_truediv),
 ('/ with big int or **', d_int_truediv_big),
 ('printf 0-flag risky',  d_printf_zero),
 ('printf % any',         d_printf_any),
]

