mpdir=json.load(open("/tmp/mu-work/mpdirs.json"))
MPMOD=[m for m in mpdir if mpdir[m]]
IMP=re.compile(r"^\s*import\s+([\w., ]+)|^\s*from\s+([\w.]+)\s+import\s+(.+)$",re.M)
def missing_attrs(p):
    miss=set()
    mods=set()
    for m in re.finditer(r"^\s*import\s+([^\n]+)",p,re.M):
        for part in m.group(1).split(","):
            part=part.strip().split(" as ")[0].strip()
            if part in mpdir and mpdir[part]: mods.add(part)
    for m in re.finditer(r"^\s*from\s+([\w.]+)\s+import\s+([^\n]+)",p,re.M):
        mod=m.group(1)
        if mod in mpdir and mpdir[mod]:
            for n in m.group(2).replace("(","").replace(")","").split(","):
                n=n.strip().split(" as ")[0].strip()
                if n and n!="*" and n not in mpdir[mod]: miss.add(mod+"."+n)
    for mod in mods:
        for m in re.finditer(r"\b%s\.(\w+)"%re.escape(mod),p):
            if m.group(1) not in mpdir[mod]: miss.add(mod+"."+m.group(1))
    return miss
