DIRS=json.load(open('/tmp/mr-check/mpdirs.json'))
MODS=set(DIRS)
hits={}
for i,t in TREES.items():
    imported=set(); alias={}
    for n in ast.walk(t):
        if isinstance(n,ast.Import):
            for a in n.names:
                imported.add(a.name); alias[a.asname or a.name.split('.')[0]]=a.name
        elif isinstance(n,ast.ImportFrom) and n.module:
            imported.add(n.module)
    miss=set()
    for n in ast.walk(t):
        if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name):
            m=alias.get(n.value.id)
            if m in MODS and DIRS[m] and n.attr not in DIRS[m]:
                miss.add(m+'.'+n.attr)
        if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Attribute) and isinstance(n.value.value,ast.Name):
            base=alias.get(n.value.value.id)
            if base:
                full=base+'.'+n.value.attr
                if full in MODS and DIRS[full] and n.attr not in DIRS[full]:
                    miss.add(full+'.'+n.attr)
        if isinstance(n,ast.ImportFrom) and n.module in MODS and DIRS[n.module]:
            for a in n.names:
                if a.name not in DIRS[n.module]: miss.add(n.module+'.'+a.name)
    if miss: hits[i]=miss
